"""Analyses SQL réelles ; fonctions spatiales GEOS et surfaces géodésiques WGS84."""
import json,sqlite3,time
from shapely.geometry import shape
from pyproj import Geod
from national.collect import ROOT,dump
ANALYSES=[
('01','Combien de communes ont une fiche climatique ?',"SELECT (SELECT count(*) FROM commune) communes,(SELECT count(*) FROM climate_place) fiches,round(100.0*(SELECT count(*) FROM climate_place)/(SELECT count(*) FROM commune),2) couverture_pct",'Couverture des fiches, pas exhaustivité des indicateurs ni précision à une adresse.'),
('02','Quelle couverture climatique par domaine ?',"SELECT domain,count(*) communes FROM climate_place GROUP BY domain ORDER BY communes DESC",'Les domaines ultramarins restent distincts de la métropole.'),
('03','Combien de communes par indicateur à 2050 ?',"SELECT i.indicator_id,i.label,i.unit,count(DISTINCT v.commune_code) communes FROM indicator i LEFT JOIN climate_value v ON v.indicator_id=i.indicator_id AND v.period_id='2050' GROUP BY i.indicator_id",'Une commune peut avoir plusieurs saisons ; le dénominateur porte sur les communes.'),
('04','Comment comparer les jours très chauds des lieux de test ?',"SELECT c.name,v.period_id,v.value,v.lower,v.upper,i.unit FROM test_place t JOIN commune c ON c.code=t.commune_code JOIN climate_value v ON v.commune_code=c.code JOIN indicator i USING(indicator_id) WHERE v.indicator_id='S1' AND v.season='annuel' AND v.period_id='2050' ORDER BY c.name",'Même indicateur et horizon ; les domaines et les références doivent aussi être examinés.'),
('05','Quelle évolution publiée entre 2030 et 2100 ?',"WITH v AS (SELECT commune_code,period_id,value,LAG(value) OVER(PARTITION BY commune_code ORDER BY CAST(period_id AS INTEGER)) preceding FROM climate_value WHERE indicator_id='S1' AND season='annuel' AND period_id IN ('2030','2100')) SELECT c.name,v.value jours_2100,round(v.value-v.preceding,2) difference_2030_2100 FROM v JOIN commune c ON c.code=v.commune_code WHERE period_id='2100' AND c.code IN ('75056','17300','13004','2A004','97411')",'Différence entre niveaux publiés, pas prédiction annuelle ni interpolation.'),
('06','Quels aléas sont recensés dans les communes ?',"SELECT h.label,count(*) communes FROM commune_hazard ch JOIN hazard h USING(hazard_id) GROUP BY h.hazard_id ORDER BY communes DESC",'Recensement communal ; aucun logement individuel ne peut être déclaré exposé à partir de ce tableau.'),
('07','Combien de géométries d’aléas sont intégrées ?',"SELECT hazard_id,raw_id,count(*) zones FROM hazard_zone GROUP BY hazard_id,raw_id",'Couverture locale Toulouse et Bordeaux seulement.'),
('08','Quelles surfaces géodésiques pour les enveloppes de Toulouse ?',"SELECT label,scenario,round(area_m2(geometry)/1000000,3) km2 FROM hazard_zone WHERE hazard_id='river_flood'",'Surfaces calculées sur ellipsoïde WGS84 après réparation documentée. Scénarios se recouvrant : ne pas sommer.'),
('09','Les lieux de test intersectent-ils les couches livrées ?',"SELECT p.label,z.hazard_id,sum(i.intersects) intersections,count(*) zones_examinees FROM spatial_intersection i JOIN test_place p USING(place_id) JOIN hazard_zone z USING(zone_id) GROUP BY p.place_id,z.hazard_id",'Absence d’intersection souvent hors couverture ; ne signifie jamais sans risque.'),
('10','Quelles parcelles recoupent plusieurs zones ?',"SELECT p.parcel_id,count(*) zones FROM parcel p JOIN parcel_zone z USING(parcel_id) GROUP BY p.parcel_id HAVING count(*)>1",'Échantillon de parcelles, pas inventaire national ; plusieurs zones n’interdisent pas automatiquement un projet.'),
('11','Quels documents ont des dates renseignées ?',"SELECT count(*) documents,sum(approval_date IS NOT NULL AND approval_date!='') approbations,sum(publication_date IS NOT NULL AND publication_date!='') publications FROM urban_document",'Complétude des métadonnées ; une date ne suffit pas à prouver l’opposabilité.'),
('12','Comment se répartissent les occurrences retenues ?',"SELECT d.code,d.name,count(*) occurrences,count(DISTINCT s.site_id) collections FROM fossil_occurrence o JOIN fossil_site s USING(site_id) JOIN department d ON d.code=s.department GROUP BY d.code ORDER BY occurrences DESC",'Biais de prospection et de publication : aucune mesure d’abondance animale.'),
('13','Quels intervalles géologiques sont documentés ?',"SELECT i.early_name,count(*) occurrences FROM fossil_occurrence o JOIN geological_interval i USING(interval_id) GROUP BY i.early_name ORDER BY occurrences DESC LIMIT 25",'Intervalles de datation ; pas années de découverte.'),
('14','Quelle précision de localisation est déclarée ?',"SELECT coordinate_basis,coordinate_precision,count(*) collections FROM fossil_site GROUP BY coordinate_basis,coordinate_precision ORDER BY collections DESC",'Les champs source restent déclaratifs ; les contours administratifs sont simplifiés à 100 m.'),
('15','Quelle couverture des médias par catégorie ?',"SELECT m.category,count(DISTINCT m.media_id) images,count(DISTINCT tm.taxon_id) taxons,count(DISTINCT o.occurrence_id) occurrences,round(100.0*count(DISTINCT o.occurrence_id)/(SELECT count(*) FROM fossil_occurrence),3) couverture_pct FROM media m LEFT JOIN taxon_media tm USING(media_id) LEFT JOIN fossil_occurrence o USING(taxon_id) GROUP BY m.category",'Illustrations taxonomiques ; aucune photo n’est présentée comme un spécimen local exact.'),
('16','Quelles publications documentent le plus d’occurrences ?',"SELECT b.reference_id,substr(b.citation,1,150) citation,count(*) occurrences FROM bibliography b JOIN fossil_occurrence o USING(reference_id) GROUP BY b.reference_id ORDER BY occurrences DESC LIMIT 10",'Concentration bibliographique et non abondance paléontologique.'),
('17','Sensibilité à une contrainte personnelle de chaleur ?',"WITH thresholds(t) AS (VALUES(5),(10),(20)) SELECT t,c.name,v.value,CASE WHEN v.value IS NULL THEN 'à documenter' WHEN v.value<=t THEN 'seuil respecté sur cet indicateur' ELSE 'seuil dépassé' END resultat FROM thresholds CROSS JOIN test_place p JOIN commune c ON c.code=p.commune_code LEFT JOIN climate_value v ON v.commune_code=c.code AND v.indicator_id='S1' AND v.period_id='2050' AND v.season='annuel' ORDER BY t,c.name",'Sensibilité d’une contrainte choisie, sans score ni verdict immobilier. Un manque ne satisfait jamais la contrainte.'),
('18','Quelles provenances et volumes ont été conservés ?',"SELECT s.producer,count(*) fichiers,sum(r.bytes) octets_originaux,min(r.retrieved_at) debut,max(r.retrieved_at) fin FROM raw_file r JOIN dataset_version d USING(version_id) JOIN source s USING(source_id) GROUP BY s.source_id",'Octets avant compression sans perte ; les dates décrivent la collecte et non la date des phénomènes.')]
def main():
 db=sqlite3.connect('file:'+str(ROOT/'data/curated/france.sqlite')+'?mode=ro',uri=True);db.row_factory=sqlite3.Row;geod=Geod(ellps='WGS84')
 db.create_function('area_m2',1,lambda s:abs(geod.geometry_area_perimeter(shape(json.loads(s)))[0]))
 db.create_function('intersects',2,lambda a,b:int(shape(json.loads(a)).intersects(shape(json.loads(b)))))
 results=[];sql=[];md=['# Analyses SQL réellement exécutées','Les fonctions area_m2 et intersects sont enregistrées par `python -m national.analyses`. Les autres requêtes sont du SQLite standard.']
 for id,question,q,meaning in ANALYSES:
  t=time.perf_counter();rows=[dict(r) for r in db.execute(q)];results.append({'id':id,'question':question,'sql':q,'rows':rows,'seconds':round(time.perf_counter()-t,4),'interpretation':meaning});sql.append('-- '+id+' '+question+'\n-- '+meaning+'\n'+q+';');md+=['## '+id+' — '+question,meaning,'```sql',q+';','```','```json',json.dumps(rows[:12],ensure_ascii=False,indent=2),'```',f'{len(rows)} lignes calculées ; résultat intégral dans reports/france_analyses.json.']
 (ROOT/'sql/france_analyses.sql').write_text('\n\n'.join(sql),encoding='utf-8');(ROOT/'docs/analyses_france.md').write_text('\n\n'.join(md),encoding='utf-8');dump(ROOT/'reports/france_analyses.json',results);print('18 analyses exécutées')
if __name__=='__main__':main()
